from collections import deque

def fill(H,W, walls):
    walls=set(walls); seen=set(); q=deque()
    for r in range(H):
        for c in (0,W-1):
            if (r,c) not in walls and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if (r,c) not in walls and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(r+dr,c+dc)
            if 0<=p[0]<H and 0<=p[1]<W and p not in walls and p not in seen:
                seen.add(p);q.append(p)
    return {(r,c) for r in range(H) for c in range(W) if (r,c) not in walls and (r,c) not in seen}
